/**
 * Notification sounds: built-in originals (public/sounds/*.wav, generated by
 * scripts/generate-sounds.py) and user-uploaded files stored in db.assets (kind 'sound').
 */
import type { AssetRecord } from '@/core/db/db';
import { getDb } from '@/core/db/db';
import { newId } from '@/core/util/id';

export const BUILTIN_SOUND_IDS = ['chime', 'register', 'bell', 'pop', 'alert', 'soft'] as const;
export type BuiltinSoundId = (typeof BUILTIN_SOUND_IDS)[number];

export const BUILTIN_SOUNDS: readonly { id: BuiltinSoundId; path: string }[] = BUILTIN_SOUND_IDS.map(
  (id) => ({ id, path: `/sounds/${id}.wav` }),
);

export const CUSTOM_SOUND_PREFIX = 'custom:';
export const MAX_SOUND_BYTES = 1024 * 1024;
export const MAX_CUSTOM_SOUNDS = 20;

export type SoundRef =
  { kind: 'builtin'; id: BuiltinSoundId; path: string } | { kind: 'custom'; assetId: string };

export function isBuiltinSoundPath(path: string): boolean {
  return BUILTIN_SOUNDS.some((s) => s.path === path);
}

/** `chime` → built-in; `custom:<assetId>` → uploaded asset; anything else → null (no sound). */
export function resolveSoundRef(soundId: string): SoundRef | null {
  if (soundId.startsWith(CUSTOM_SOUND_PREFIX)) {
    const assetId = soundId.slice(CUSTOM_SOUND_PREFIX.length);
    return /^[\w-]{1,80}$/.test(assetId) ? { kind: 'custom', assetId } : null;
  }
  const builtin = BUILTIN_SOUNDS.find((s) => s.id === soundId);
  return builtin ? { kind: 'builtin', id: builtin.id, path: builtin.path } : null;
}

export type SoundFileError = 'empty' | 'too_large' | 'not_audio';

export function validateSoundFile(file: {
  type: string;
  size: number;
}): { ok: true } | { ok: false; error: SoundFileError } {
  if (!file.size) return { ok: false, error: 'empty' };
  if (file.size > MAX_SOUND_BYTES) return { ok: false, error: 'too_large' };
  if (!/^audio\/[\w.+-]+$/i.test(file.type.trim())) return { ok: false, error: 'not_audio' };
  return { ok: true };
}

export function soundDisplayName(fileName: string): string {
  const base = fileName
    .replace(/\.[a-z0-9]{1,5}$/i, '')
    .replace(/[^\p{L}\p{N} ._-]/gu, '')
    .trim();
  return (base || 'Sound').slice(0, 60);
}

export async function listCustomSounds(): Promise<AssetRecord[]> {
  const rows = await getDb().assets.where('kind').equals('sound').toArray();
  return rows.sort((a, b) => b.createdAt - a.createdAt);
}

export async function addCustomSound(file: Blob, name: string, now = Date.now()): Promise<AssetRecord> {
  const check = validateSoundFile(file);
  if (!check.ok) throw new Error(`Sound rejected: ${check.error}`);
  const db = getDb();
  return db.transaction('rw', db.assets, async () => {
    const count = await db.assets.where('kind').equals('sound').count();
    if (count >= MAX_CUSTOM_SOUNDS)
      throw new Error(`Sound rejected: limit of ${MAX_CUSTOM_SOUNDS} custom sounds reached`);
    const rec: AssetRecord = {
      id: newId('snd'),
      kind: 'sound',
      name: soundDisplayName(name),
      mime: file.type.toLowerCase(),
      blob: file,
      createdAt: now,
    };
    await db.assets.add(rec);
    return rec;
  });
}

export async function deleteCustomSound(assetId: string): Promise<void> {
  const db = getDb();
  const rec = await db.assets.get(assetId);
  if (rec && rec.kind === 'sound') await db.assets.delete(assetId);
}
